SELECT d, m, g, g / prev - 1 FROM (SELECT d, m, g, LAG(g, 1) OVER (PARTITION BY d ORDER BY m) AS prev FROM ( SELECT rg.name AS d, CAST(strftime(o.order_at, '%Y-%m-01') AS DATE) AS m, SUM(CASE WHEN o.currency = 'BDT' THEN o.total_bdt ELSE o.total_amount * x.bdt_per_unit END) AS g FROM orders o LEFT JOIN currency_rates x ON x.rate_date = CAST(o.order_at AS DATE) AND x.currency = o.currency JOIN customer_addresses ad USING (address_id) JOIN cities c ON c.city_id = ad.city_id JOIN regions rg ON rg.region_id = c.region_id WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-01-01 00:00:00' AND o.order_at < TIMESTAMP '2025-01-01 00:00:00' GROUP BY 1, 2) t) u ORDER BY d, m
